class Widget {
public:
    using DataType = std::vector<double>;

    // Only for lvalue Widgets: return a reference
    DataType& data() & {
        return values;
    }

    // Only for rvalue Widgets: return a value (by move)
    DataType data() && {
        return std::move(values);
    }

private:
    DataType values;
};

Widget makeWidget();

Widget w;
auto& v1 = w.data();           // Calls lvalue-qualified version
auto v2 = makeWidget().data(); // Calls rvalue-qualified version
